#!/usr/bin/env bash
# FirstPass: full question bank, faster startup. No lazy per-system loading.
set -euo pipefail
for path in package.json vite.config.ts src/lib/data.ts src/lib/store.tsx src/components/DoctorWalk.tsx; do
  if [ ! -f "$path" ]; then echo "Missing $path; open the FirstPass project root." >&2; exit 1; fi
done
if ! grep -Fq "loadBundledQuestions" src/lib/store.tsx; then
  echo "Your installed version differs from the expected FirstPass build. No files changed." >&2
  exit 1
fi
if ! grep -Fq "import.meta.glob" src/lib/data.ts; then
  echo "Question loading has already changed. No files changed." >&2
  exit 1
fi
if grep -Fq "pathsForSystem" src/lib/store.tsx; then
  echo "A per-system loading update seems installed; this script targets your earlier full-bank version." >&2
  exit 1
fi
backup_dir=$(mktemp -d ./firstpass-before-compressed-XXXXXX)
mkdir -p "$backup_dir/src/lib" "$backup_dir/src/components" "$backup_dir/public"
cp vite.config.ts "$backup_dir/vite.config.ts"
cp src/lib/data.ts "$backup_dir/src/lib/data.ts"
cp src/components/DoctorWalk.tsx "$backup_dir/src/components/DoctorWalk.tsx"
for file in firstpass-bank.fpb firstpass-bank.json; do
  if [ -f "public/$file" ]; then cp "public/$file" "$backup_dir/public/$file"; fi
done
echo "Source backup saved: $backup_dir"
mkdir -p scripts src/assets
cat <<'FIRSTPASS_FULLBANK_PLUGIN_EOF' > scripts/firstpassBank.ts
import type { Plugin } from 'vite'
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { gzipSync } from 'node:zlib'

const dataDir = resolve(process.cwd(), 'src/data')
const publicDir = resolve(process.cwd(), 'public')

// Read-only access to src/data/*.json. Generated files live in public/ instead.
function buildCompressedBank(): void {
  const entries: { name: string; raw: unknown }[] = []
  if (existsSync(dataDir)) {
    for (const name of readdirSync(dataDir).filter((file) => file.endsWith('.json')).sort()) {
      entries.push({ name, raw: JSON.parse(readFileSync(join(dataDir, name), 'utf8').replace(/^\uFEFF/, '')) })
    }
  }
  const json = JSON.stringify({ files: entries })
  mkdirSync(publicDir, { recursive: true })
  writeFileSync(join(publicDir, 'firstpass-bank.fpb'), gzipSync(json, { level: 7 }))
  // Compatibility fallback for older browsers without DecompressionStream.
  writeFileSync(join(publicDir, 'firstpass-bank.json'), json)
}

export function firstpassCompressedBank(): Plugin {
  // Generate the package before Vite scans public/ for static assets.
  buildCompressedBank()
  return {
    name: 'firstpass-compressed-full-bank',
    configureServer(server) {
      const refresh = (file: string) => {
        if (file.startsWith(dataDir) && file.endsWith('.json')) {
          buildCompressedBank()
          server.ws.send({ type: 'full-reload' })
        }
      }
      server.watcher.on('add', refresh)
      server.watcher.on('change', refresh)
      server.watcher.on('unlink', refresh)
    },
  }
}
FIRSTPASS_FULLBANK_PLUGIN_EOF
node <<'FIRSTPASS_FULLBANK_PATCH_EOF'
const fs = require('node:fs')
const nextTail = Buffer.from('', 'base64').toString('utf8')
const updates = []
function plan(path, transform) {
  const old = fs.readFileSync(path, "utf8")
  const next = transform(old)
  if (old === next) throw new Error("No change prepared for " + path)
  updates.push({ path, next })
}
function replaceOnce(text, before, after, path) {
  if (!text.includes(before)) throw new Error("Unexpected " + path + "; source left unchanged")
  return text.replace(before, after)
}
plan("vite.config.ts", (text) => {
  let out = replaceOnce(text, "import tailwindcss from '@tailwindcss/vite'", "import tailwindcss from '@tailwindcss/vite'\nimport { firstpassCompressedBank } from './scripts/firstpassBank.ts'", "vite.config.ts")
  out = replaceOnce(out, "plugins: [react(), tailwindcss()", "plugins: [react(), tailwindcss(), firstpassCompressedBank()", "vite.config.ts")
  return out
})
plan("src/components/DoctorWalk.tsx", (text) => {
  let out = replaceOnce(text, "../assets/doctor-male-a.png", "../assets/doctor-male-optimized.webp", "DoctorWalk.tsx")
  out = replaceOnce(out, "../assets/doctor-female-a.png", "../assets/doctor-female-optimized.webp", "DoctorWalk.tsx")
  return out
})
plan("src/lib/data.ts", (text) => {
  const marker = "export const BUNDLED_FILES: BundledFile[] = []"
  if (!text.includes(marker) || !text.includes("loadBundledQuestions") || !text.includes("import.meta.glob")) throw new Error("Unknown data.ts layout; no code overwritten")
  return text.slice(0, text.indexOf(marker)) + nextTail
})
for (const update of updates) fs.writeFileSync(update.path, update.next)
console.log("Updated the compressed loader; existing UI, store, and progress keys were preserved.")
FIRSTPASS_FULLBANK_PATCH_EOF
